import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";

export const fps = 25;

const COLORS = {
  accent: "#FFFFFF",
  accentSoft: "rgba(255,255,255,0.6)",
  ink: "#FFFFFF",
  inkDim: "rgba(255,255,255,0.55)",
  ring: "rgba(255,255,255,0.08)",
  bg: "#0B0610",
};

const TRANSITION = 15;

const SNAPPY = { mass: 0.5, damping: 14, stiffness: 220 };
const LIQUID = { mass: 1.0, damping: 22, stiffness: 120 };

// ─── Scene durations ────────────────────────────────────────────────────
const COUNT_DURATION = 90; // ~3.6s of ticking up
const FREEZE_DURATION = 250; // 10s freeze on 20:00
const CLOCK_SCENE = COUNT_DURATION + FREEZE_DURATION; // 340

const BlackScreen: React.FC = () => (
  <AbsoluteFill style={{ backgroundColor: COLORS.bg }} />
);

// ─── Clock Scene ────────────────────────────────────────────────────────
const ClockScene: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Entrance — compound: opacity + scale + blur (no bounce, no rotate)
  const enter = spring({ frame, fps, delay: 4, config: LIQUID });
  const entryScale = interpolate(enter, [0, 1], [0.92, 1]);
  const entryBlur = interpolate(enter, [0, 1], [10, 0]);

  // Counting progress (0 → 1 across COUNT_DURATION, then clamped)
  const countStart = 10;
  const countEnd = countStart + COUNT_DURATION;
  const rawProgress = interpolate(frame, [countStart, countEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  // Ease-out for a satisfying settle on 20:00
  const eased = 1 - Math.pow(1 - rawProgress, 2.2);
  const totalSeconds = Math.floor(eased * 20 * 60); // 0 → 1200
  const minutes = Math.floor(totalSeconds / 60);
  const seconds = totalSeconds % 60;
  const mm = String(minutes).padStart(2, "0");
  const ss = String(seconds).padStart(2, "0");

  // Ring sweep angle (0 → 360deg)
  const sweepAngle = eased * 360;

  // Clock size
  const size = 1600;
  const stroke = 32;
  const radius = (size - stroke) / 2;
  const circumference = 2 * Math.PI * radius;
  const dashOffset = circumference * (1 - eased);

  return (
    <AbsoluteFill style={{ fontFamily: "'Inter', sans-serif" }}>
      {/* Clock — centered, no bounce, no drift */}
      <div
        style={{
          position: "absolute",
          left: "50%",
          top: "50%",
          transform: `translate(-50%, -50%) scale(${entryScale})`,
          opacity: enter,
          filter: `blur(${entryBlur}px)`,
          width: size,
          height: size,
        }}
      >
        {/* SVG dial */}
        <svg
          width={size}
          height={size}
          viewBox={`0 0 ${size} ${size}`}
          style={{
            position: "absolute",
            inset: 0,
          }}
        >
          {/* Outer faint ring */}
          <circle
            cx={size / 2}
            cy={size / 2}
            r={radius}
            stroke={COLORS.ring}
            strokeWidth={stroke}
            fill="none"
          />
          {/* Tick marks (60 ticks, every 5th larger) */}
          {Array.from({ length: 60 }).map((_, i) => {
            const angle = (i / 60) * 360 - 90;
            const rad = (angle * Math.PI) / 180;
            const isMajor = i % 5 === 0;
            const inner = radius - (isMajor ? 70 : 38);
            const outer = radius - 16;
            const x1 = size / 2 + Math.cos(rad) * inner;
            const y1 = size / 2 + Math.sin(rad) * inner;
            const x2 = size / 2 + Math.cos(rad) * outer;
            const y2 = size / 2 + Math.sin(rad) * outer;
            const passed = (i / 60) * 360 <= sweepAngle;
            return (
              <line
                key={i}
                x1={x1}
                y1={y1}
                x2={x2}
                y2={y2}
                stroke={
                  passed
                    ? isMajor
                      ? "#FFFFFF"
                      : "rgba(255,255,255,0.7)"
                    : isMajor
                    ? "rgba(255,255,255,0.35)"
                    : "rgba(255,255,255,0.12)"
                }
                strokeWidth={isMajor ? 7 : 3.5}
                strokeLinecap="round"
              />
            );
          })}

          {/* Progress arc — sweeps with the count */}
          <circle
            cx={size / 2}
            cy={size / 2}
            r={radius}
            stroke="#FFFFFF"
            strokeWidth={stroke}
            fill="none"
            strokeDasharray={circumference}
            strokeDashoffset={dashOffset}
            strokeLinecap="round"
            transform={`rotate(-90 ${size / 2} ${size / 2})`}
          />
        </svg>

        {/* Center readout */}
        <div
          style={{
            position: "absolute",
            inset: 0,
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            justifyContent: "center",
          }}
        >
          <div
            style={{
              fontFamily: "'Inter', sans-serif",
              fontSize: 440,
              fontWeight: 800,
              color: COLORS.ink,
              lineHeight: 1,
              letterSpacing: "-0.06em",
              display: "flex",
              alignItems: "center",
              gap: 8,
            }}
          >
            <span style={{ minWidth: 440, textAlign: "right" }}>{mm}</span>
            <span style={{ color: "rgba(255,255,255,0.85)" }}>:</span>
            <span style={{ minWidth: 440, textAlign: "left" }}>{ss}</span>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

// ─── Main composition ───────────────────────────────────────────────────
const MainComposition: React.FC = () => {
  return (
    <TransitionSeries>
      <TransitionSeries.Sequence durationInFrames={20}>
        <BlackScreen />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: 20 })}
      />

      <TransitionSeries.Sequence durationInFrames={CLOCK_SCENE + TRANSITION}>
        <ClockScene />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      <TransitionSeries.Sequence durationInFrames={25}>
        <BlackScreen />
      </TransitionSeries.Sequence>
    </TransitionSeries>
  );
};

export const durationInFrames = 365;

export default MainComposition;
